<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref } from 'vue'
import type { Plan, SampleData } from '../types'
import { navigate, notify, savePlan, state } from '../state'
import Icon from './Icon.vue'
type ChatMessage = { id: string; role: 'user' | 'assistant'; parts: { type: 'text'; text: string }[] }
const props = defineProps<{ data: SampleData }>()
const input = ref(''), busy = ref(false), status = ref<'ready' | 'submitted' | 'streaming' | 'error'>('ready'), step = ref(''), stopped = ref(false), lastPrompt = ref(''), tab = ref('workspace'), sourceOpen = ref(false), preview = ref<{ id: string; before: string; after: string; planNumber: string; productName: string } | null>(null), result = ref(''), note = ref('请优先核对本计划的物料与交付日期'), target = ref(props.data.plans[0]?.id || '')
const progress = ref(0), trace = ref<string[]>([])
const initial = `我可以帮你梳理当前 F006 的生产计划、成本和工序关系。\n\n已收录 ${props.data.plans.length} 张生产计划、${props.data.batches.length} 条生产批次记录，以及 ${props.data.workflows.length} 套非空工序配置。你可以先问“哪些计划正在进行？”，也可以生成一条计划备注的本机修改预览。`
const messages = ref<ChatMessage[]>([{ id: 'welcome', role: 'assistant', parts: [{ type: 'text', text: initial }] }])
try { const stored = localStorage.getItem('cretas-v5-ai-messages'); if (stored) messages.value = JSON.parse(stored) } catch { /* keep initial */ }
let controller: AbortController | undefined
const plans = computed(() => props.data.plans.map(p => ({ ...p, ...state.planOverrides[p.id] })))
const selectedPlan = computed(() => plans.value.find(p => p.id === target.value))
const money = (v: unknown) => typeof v === 'number' ? v.toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '未提供'
function persist() { try { localStorage.setItem('cretas-v5-ai-messages', JSON.stringify(messages.value)) } catch { notify('对话暂未保存到本机，当前回答仍可查看。') } }
async function copyAnswer(text: string) { try { await navigator.clipboard.writeText(text); notify('已复制回答。') } catch { notify('浏览器未允许复制，请手动选中回答复制。') } }
function copyMessage(message: ChatMessage) { return copyAnswer(message.parts.map(p => p.text).join('\n')) }
function exportChat() { const text = messages.value.map(m => (m.role === 'user' ? '我' : 'Cretas 业务助手（快照规则）') + '\n' + m.parts.map(p => p.text).join('\n')).join('\n\n'); const url = URL.createObjectURL(new Blob([text], {type: 'text/plain;charset=utf-8'})); const a = document.createElement('a'); a.href = url; a.download = 'F006-本机对话.txt'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
function answer(prompt: string): string {
  if (/工序|流程|画布/.test(prompt)) { const w = props.data.workflows.find(w => w.nodes.length >= 5 && w.nodes.length <= 7) || props.data.workflows[0]; return w ? `已找到 ${props.data.workflows.length} 套有实际工序内容的配置。\n\n以“${w.name}”为例，源记录包含 ${w.nodes.length} 道工序：${w.nodes.map(n => n.label).join('、')}。\n\n画布连接通过真实投入和产出的 materialNodeId 匹配重建；节点位置是新界面布局。没有匹配依据的工艺关系不会自动补线。正式修改工艺仍需业务校验和发布审批。` : '当前快照没有可用工序配置，无法生成工艺关系。' }
  if (/成本|费用|金额|财务/.test(prompt)) { const s = props.data.analytics.cost.summary; return `已读取 F006 源成本报表。\n\n覆盖批次：${s.batchCount ?? '未提供'} 批\n记录成本合计：¥${money(s.totalCost)}\n物料成本：¥${money(s.totalMaterialCost)}\n人工成本：¥${money(s.totalLaborCost)}\n\n这些是已收录统计行的报表口径，不是全厂总成本，也不能作为销售利润。缺失的出成率、销售收入和未提供的单位不作推断。` }
  if (/销售|利润|增长|同比/.test(prompt)) return '当前经营驾驶舱快照返回“当前时间范围内暂无销售数据”，KPI 和图表列表为空。\n\n我无法据此判断营收、利润或增长率。可以查看已有生产计划和成本报表，或先补齐销售数据后再分析。'
  if (/生产|计划|进行|交付|状态/.test(prompt)) { const running = plans.value.filter(p => p.status === 'IN_PROGRESS'), pending = plans.value.filter(p => p.status === 'PENDING'); return `当前已收录 ${plans.value.length} 张生产计划，其中进行中 ${running.length} 张、待开始 ${pending.length} 张。\n\n正在进行的计划包括：\n${running.slice(0, 5).map(p => `• ${p.productName}｜${p.planNumber}｜${p.plannedQuantity ?? '未提供'} ${p.plannedUnit}`).join('\n')}\n\n计划中的 QA／演示标识已保留。不同单位不合并；actualQuantity 缺失时，不会把“未报工”当作实际产量为 0。` }
  return '我保留了你的问题，但本地样板没有通用模型推理能力。\n\n可以演示：生产计划状态、源成本报表、工序投入产出关系，以及计划备注的“预览 → 确认 → 保存本机草稿”。未收录的信息会明确说明，不补造业务结论。'
}
async function send(prompt = input.value) {
  if (!prompt.trim() || busy.value) return; input.value = ''; lastPrompt.value = prompt; result.value = ''; stopped.value = false; preview.value = null; trace.value = []; progress.value = 0; busy.value = true; status.value = 'submitted'; controller = new AbortController(); const signal = controller.signal
  messages.value.push({ id: crypto.randomUUID(), role: 'user', parts: [{ type: 'text', text: prompt }] }); const m: ChatMessage = { id: crypto.randomUUID(), role: 'assistant', parts: [{ type: 'text', text: '' }] }; messages.value.push(m); const messageId = m.id
  const pause = async (ms: number) => { await new Promise(resolve => setTimeout(resolve, ms)); if (signal.aborted) throw new DOMException('Aborted', 'AbortError') }
  try { step.value = '读取 F006 账号快照'; await pause(250); trace.value.push('已读取当前账号范围'); progress.value = 1; step.value = '核对记录、单位和数据来源'; await pause(260); trace.value.push('已核对来源与缺失值'); progress.value = 2; status.value = 'streaming'; step.value = '呈现快照分析结果'; const text = answer(prompt); for (let i = 0; i < text.length; i += 17) { await pause(24); const row = messages.value.find(x => x.id === messageId); if (row) row.parts[0].text = text.slice(0, i + 17) } trace.value.push('结果可追溯至源记录'); progress.value = 3; persist() }
  catch (e) { if (signal.aborted) { stopped.value = true; const row = messages.value.find(x => x.id === messageId); if (row && !row.parts[0].text) row.parts[0].text = '本次分析已停止。你的问题保留，可以重试。' } else { status.value = 'error'; notify(e instanceof Error ? e.message : '分析未完成，请重试。') } }
  finally { busy.value = false; if (status.value !== 'error') status.value = 'ready'; persist(); await nextTick() }
}
function keydown(e: KeyboardEvent) { if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); send() } }
function prepare() { if (!selectedPlan.value) return; const p = selectedPlan.value; if (!note.value.trim()) return notify('请先填写要保存的备注。'); preview.value = { id: p.id, planNumber: p.planNumber, productName: p.productName, before: p.notes || '', after: note.value }; result.value = ''; notify('已生成修改预览，请核对前后值。') }
function confirm() { const v = preview.value; if (!v || state.role !== 'factory') return notify('当前角色无法修改工厂计划。'); const current = plans.value.find(p => p.id === v.id); if (!current || (current.notes || '') !== v.before) { preview.value = null; return notify('计划草稿已变化，请重新生成预览。') } if (!savePlan(v.id, { notes: v.after })) return; const persisted = JSON.parse(localStorage.getItem('cretas-v5-plans') || '{}'); if (persisted[v.id]?.notes !== v.after) return notify('本机存储回读未通过，请重新检查草稿。'); result.value = `已保存 ${v.planNumber} 的本机备注。回读结果：${persisted[v.id].notes}`; preview.value = null }
function newChat() { controller?.abort(); messages.value = [{ id: crypto.randomUUID(), role: 'assistant', parts: [{ type: 'text', text: initial }] }]; persist(); preview.value = null; result.value = ''; notify('已开始新的本机样板对话。') }
onBeforeUnmount(() => controller?.abort())
</script>

<template>
  <div class="page-head"><div><div class="eyebrow">AI OPERATIONS</div><h1>AI 工作台 <span class="beta-label">快照交互样板</span></h1><p>从一个问题，到有依据的答案和可确认的操作。</p></div><div class="head-actions"><UButton color="neutral" variant="outline" @click="sourceOpen = true"><Icon name="book" :size="16" />数据与能力范围</UButton><UButton color="neutral" variant="outline" @click="exportChat"><Icon name="file" :size="16" />导出对话</UButton><UButton :disabled="busy" @click="newChat"><Icon name="plus" :size="16" />新建对话</UButton></div></div>
  <div class="ai-layout"><section class="surface conversation"><div class="conversation-top"><div><span class="assistant-mark"><Icon name="ai" :size="21" /></span><strong>Cretas 业务助手</strong><span class="online-label"><i class="dot green" />本地数据就绪</span></div><div class="tab-list"><button :class="{ active: tab === 'workspace' }" @click="tab = 'workspace'">对话</button><button :class="{ active: tab === 'records' }" @click="tab = 'records'">原账号执行记录 <span>{{ data.aiExamples.length }}</span></button></div></div>
    <div v-if="tab === 'workspace'" class="conversation-scroll"><div class="context-line"><Icon name="shield" :size="14" />工厂超级管理员 · F006 · 只分析已收录数据</div><UChatMessages :messages="messages" :status="status" :should-auto-scroll="true" :user="{ variant: 'soft' }" :assistant="{ variant: 'naked' }" :ui="{ root: 'sample-chat-messages' }"><template #content="{ message }"><div :class="['chat-message-content', message.role]"><div v-if="message.role === 'assistant'" class="answer-label"><Icon name="ai" :size="15" />快照规则分析</div><div v-for="(part, i) in message.parts" :key="i" class="answer-text">{{ 'text' in part ? part.text : '' }}</div><div v-if="message.role === 'assistant' && !busy" class="answer-actions"><button class="evidence-link" @click="copyMessage(message)"><Icon name="copy" :size="13" />复制回答</button><button class="evidence-link" @click="sourceOpen = true"><Icon name="book" :size="13" />核对数据来源</button><button class="evidence-link" @click="navigate('plans')">查看计划<Icon name="arrow" :size="13" /></button><button class="evidence-link" @click="navigate('canvas')">查看工序<Icon name="arrow" :size="13" /></button></div></div></template></UChatMessages>
      <div v-if="messages.length === 1" class="ai-starters"><span>从这些工作开始</span><div><button @click="send('哪些生产计划正在进行？')"><Icon name="plans" :size="21" /><strong>梳理生产计划</strong><p>{{ data.plans.length }} 张计划的状态与下一步</p><Icon name="arrow" :size="15" /></button><button @click="send('解释当前成本构成')"><Icon name="chart" :size="21" /><strong>理解成本构成</strong><p>查看报表依据与统计口径</p><Icon name="arrow" :size="15" /></button><button @click="send('工序关系有哪些来源？')"><Icon name="canvas" :size="21" /><strong>核对工序关系</strong><p>{{ data.workflows.length }} 套配置与真实投入产出</p><Icon name="arrow" :size="15" /></button></div></div>
      <div v-if="busy" class="thinking-status" role="status"><span class="loading-dot" /><div>{{ step }}<small>{{ trace.join(' · ') }}</small></div><span>{{ progress }}/3</span></div><div v-if="stopped" class="stopped-note"><Icon name="stop" :size="14" />已停止本次分析<UButton color="neutral" variant="ghost" size="xs" @click="send(lastPrompt)">重试</UButton></div>
    </div>
    <div v-else class="execution-records"><div v-if="!data.aiExamples.length" class="empty-block">源快照没有执行记录</div><details v-for="(example, i) in data.aiExamples" :key="i" class="execution-record"><summary><span class="record-index">{{ String(i + 1).padStart(2, '0') }}</span><div><strong>{{ example.response.intentName || example.prompt }}</strong><small>{{ example.response.intentCode }} · {{ example.response.status }}</small></div><Icon name="down" :size="15" /></summary><p class="answer-text">{{ example.response.formattedText || example.response.message || '源记录未提供文本结果' }}</p><pre class="source-json">{{ JSON.stringify(example.response, null, 2) }}</pre></details></div>
    <div class="composer"><div class="suggestion-row"><button @click="tab = 'workspace'; send('哪些生产计划正在进行？')">查看进行中的计划</button><button @click="tab = 'workspace'; send('解释当前成本构成')">解释成本构成</button><button @click="tab = 'workspace'; send('工序关系有哪些来源？')">核对工序关系</button></div><div class="composer-input"><textarea v-model="input" placeholder="询问计划、成本或工序关系…" aria-label="向业务助手提问" rows="2" @keydown="keydown" /><div><span><Icon name="layers" :size="13" />F006 账号快照</span><UButton v-if="busy" color="neutral" variant="outline" aria-label="停止分析" @click="controller?.abort()"><Icon name="stop" :size="17" /></UButton><UButton v-else :disabled="!input.trim()" aria-label="发送问题" @click="send()"><Icon name="send" :size="17" /></UButton></div></div><p>Enter 发送 · Shift + Enter 换行 · 本地规则演示，不调用线上模型</p></div>
  </section>
  <aside class="ai-context"><section class="surface"><div class="panel-heading"><h3>当前工作范围</h3><Icon name="shield" :size="17" /></div><div class="context-factory"><span class="tenant-avatar"><Icon name="factory" :size="22" /></span><div><strong>{{ data.factoryName }}</strong><small>F006 · {{ data.userName }}</small></div></div><div class="property-pair"><span>生产计划</span><b>{{ data.plans.length }} 张</b></div><div class="property-pair"><span>工序配置</span><b>{{ data.workflows.length }} 套</b></div><div class="property-pair"><span>数据状态</span><b>账号快照</b></div></section>
    <section class="surface action-preview"><div class="panel-heading"><h3>受控操作演示</h3><span class="status-badge gray">本机</span></div><p>修改备注前，先预览影响，再确认保存。</p><label class="property-field">目标计划<USelect v-model="target" :items="plans.map(p => ({ label: p.productName + ' · ' + p.planNumber.slice(-8), value: p.id }))" aria-label="选择备注目标计划" /></label><label class="property-field">新备注<UTextarea v-model="note" :rows="3" aria-label="计划新备注" /></label><UButton block color="neutral" variant="outline" @click="prepare" data-testid="preview-action"><Icon name="file" :size="15" />生成修改预览</UButton>
      <div v-if="preview" class="change-preview"><span class="eyebrow">等待你的确认</span><h4>{{ preview.productName }}</h4><div class="diff old"><small>修改前</small>{{ preview.before || '空备注' }}</div><div class="diff new"><small>修改后</small>{{ preview.after }}</div><p>影响 1 张计划的本机草稿，不改变数量或工艺。</p><UButton block @click="confirm" data-testid="confirm-action">确认保存本机草稿</UButton><button class="text-button" @click="preview = null">取消修改</button></div><div v-if="result" class="action-result" role="status"><Icon name="check" :size="17" />{{ result }}</div></section>
  </aside></div>
  <UModal v-model:open="sourceOpen" title="当前助手的数据与能力范围" description="区分已记录的执行结果和本机交互演示" :ui="{ content: 'max-w-2xl' }"><template #body><div class="source-note"><Icon name="shield" /><div><b>f006_admin · F006 · {{ data.snapshotUpdatedAt.slice(0, 10) }}</b><p>对话答案由本机快照规则生成；流式呈现可停止，但不是线上模型调用。原账号执行记录保留源响应。写入演示只保存到本机浏览器草稿。</p></div></div><h3>可追溯的数据</h3><ul class="source-list"><li>生产计划：{{ data.plans.length }} 张，包含全部源字段</li><li>生产批次：{{ data.batches.length }} 条</li><li>工序配置：{{ data.workflows.length }} 套，按真实物料标识重建关系</li><li>成本报表：{{ data.analytics.cost.rows.length }} 个统计日</li></ul><div v-for="key in data.analytics.sourceKeys" :key="key" class="source-path">{{ key }}</div><p class="muted">缺少的营收、利润、出成率、SSE 原始事件及未采集字段不作推断。</p></template></UModal>
</template>
